SELECT order_item_id
  FROM reviews
 WHERE member_id = #{memberId}

SELECT EXISTS (
    SELECT 1
      FROM reviews
     WHERE order_item_id = #{orderItemId}
)

SELECT 
  FROM reviews
 WHERE product_id = #{productId}
   AND status = 'PUBLISHED'
 ORDER BY created_at DESC, id DESC
 LIMIT #{size} OFFSET #{offset}

SELECT 
  FROM reviews
 WHERE member_id = #{memberId}
   AND status <> 'DELETED'
 ORDER BY created_at DESC, id DESC
 LIMIT #{size} OFFSET #{offset}
